160		if err != nil {
161			if errors.Is(err, pgx.ErrNoRows) {
162				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "feature not found: "+featureID)
163			}
164			return nil, err
165		}
166	
167		f, err = a.q.GetWorkspaceFeature(ctx, database.GetWorkspaceFeatureParams{
168			WorkspaceID: uid,
169			FeatureID:   featureUUID,
170		})
171		if err != nil {
172			if errors.Is(err, pgx.ErrNoRows) {
173				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "feature not found: "+featureID)
174			}
175			return nil, dbErr("get feature", err)
176		}
177	
178		docs, err := a.q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
179			WorkspaceID: uid,
180			FeatureID:   featureUUID,
181		})
182		if err != nil {
183			return nil, dbErr("list feature documents", err)
184		}
185	
186		tasks, err := a.q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
187			WorkspaceID: uid,
