196			FeatureID:   featureUUID,
197		})
198		if err != nil {
199			return nil, dbErr("list feature activity", err)
200		}
201	
202		latestRun, runErr := a.q.GetLatestSyncRun(ctx, uid)
203		if runErr != nil && !errors.Is(runErr, pgx.ErrNoRows) {
204			log.Printf("warn: get latest sync run workspace=%s: %v", workspaceID, runErr)
205		}
206		ss := syncRunToSourceState(&latestRun, nil)
207	
208		summary := rowToFeatureSummary(f, tasks)
209	
210		docLinks := make([]domain.DocumentLink, 0, len(docs))
211		for _, d := range docs {
212			dl := domain.DocumentLink{
213				DocumentType: d.DocumentType,
214				SourcePath:   d.SourcePath,
215			}
216			if d.URL != nil {
