225		}
226	
227		activity := make([]domain.ActivityEvent, 0, len(actEvents))
228		for _, e := range actEvents {
229			activity = append(activity, rowToActivityEvent(e))
230		}
231	
232		return &domain.FeatureDetail{
233			FeatureSummary: summary,
234			WorkspaceID:    workspaceID,
235			Documents:      docLinks,
236			Tasks:          taskSummaries,
237			Activity:       activity,
238			SourceState:    ss,
239		}, nil
240	}
