420	// SaveTaskSnapshot upserts a single task's rows (workspace_tasks + activity) in a transaction.
421	func (a *Adapter) SaveTaskSnapshot(ctx context.Context, workspaceID string, snap domain.TaskSnapshot) error {
422		uid, err := parseUUID(workspaceID)
423		if err != nil {
424			return err
425		}
426	
427		_, featureUUID, err := a.resolveFeature(ctx, uid, snap.FeatureID)
428		if err != nil {
429			if !errors.Is(err, pgx.ErrNoRows) {
430				return dbErr("get feature for task sync", err)
431			}
432	
433			// A task webhook can arrive before the feature branch/full workspace sync
434			// has materialized the parent feature row. In GitHub payloads, feature_id
435			// is the human-readable feature name; create a minimal feature row and let
436			// later feature/workspace sync enrich it while preserving UUID references.
437			feature, err := a.q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
438				WorkspaceID: uid,
439				FeatureName: snap.FeatureID,
440				Title:       snap.FeatureID,
441				Stages:      json.RawMessage("[]"),
442				SourcePath:  snap.SourcePath,
443			})
444			if err != nil {
445				return fmt.Errorf("upsert placeholder feature for task sync %s: %w", snap.FeatureID, err)
446			}
447			featureUUID = feature.ID
448		}
449	
450		tx, err := a.pool.BeginTx(ctx, pgx.TxOptions{})
451		if err != nil {
452			return fmt.Errorf("begin transaction: %w", err)
453		}
454		defer tx.Rollback(ctx) //nolint:errcheck
455	
456		if err := upsertTaskSnapshot(ctx, a.q.WithTx(tx), uid, featureUUID, snap.FeatureID, snap); err != nil {
457			return err
458		}
459		return tx.Commit(ctx)
460	}
