561	// upsertSnapshot is the transactional core of SaveSnapshot.
562	func upsertSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, snap *domain.WorkspaceSnapshot) error {
563		mgmtRepoID := snap.ManagementRepoID
564		if mgmtRepoID == "" {
565			mgmtRepoID = "management-repo"
566		}
567		_, err := q.UpdateWorkspaceByID(ctx, database.UpdateWorkspaceByIDParams{
568			ID:               uid,
569			Slug:             snap.Slug,
570			Name:             snap.Name,
571			ManagementRepoID: mgmtRepoID,
572			BranchPattern:    ptrStr(snap.BranchPattern),
573		})
574		if err != nil {
575			if errors.Is(err, pgx.ErrNoRows) {
576				return domain.NewDatabaseError(domain.ErrDatabaseNotFound, "workspace not found: "+uuidStr(uid))
577			}
578			return fmt.Errorf("update workspace: %w", err)
579		}
580	
581		// Upsert repos.
582		repoIDs := make([]string, 0, len(snap.Repos))
583		for _, r := range snap.Repos {
584			bp := ptrStr(r.BaseBranch)
585			_, err := q.UpsertWorkspaceRepo(ctx, database.UpsertWorkspaceRepoParams{
586				WorkspaceID: uid,
587				RepoID:      r.RepoID,
588				BaseBranch:  bp,
589			})
590			if err != nil {
591				return fmt.Errorf("upsert repo %s: %w", r.RepoID, err)
592			}
593			repoIDs = append(repoIDs, r.RepoID)
594		}
595		if err := q.DeleteWorkspaceReposNotIn(ctx, database.DeleteWorkspaceReposNotInParams{
596			WorkspaceID: uid,
597			RepoIds:     repoIDs,
598		}); err != nil {
599			return fmt.Errorf("delete stale repos: %w", err)
600		}
601	
602		// Upsert features, docs, tasks, activity.
603		featureIDs := make([]string, 0, len(snap.Features))
604		for _, f := range snap.Features {
605			if err := upsertFeatureSnapshot(ctx, q, uid, f); err != nil {
606				return err
607			}
608			featureIDs = append(featureIDs, f.FeatureID)
609		}
610		if err := q.DeleteWorkspaceFeaturesNotIn(ctx, database.DeleteWorkspaceFeaturesNotInParams{
611			WorkspaceID:  uid,
612			FeatureNames: featureIDs,
613		}); err != nil {
614			return fmt.Errorf("delete stale features: %w", err)
615		}
616	
617		return nil
618	}
619	
620	func upsertFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
621		stages, err := json.Marshal(f.Stages)
622		if err != nil {
623			return fmt.Errorf("marshal stages for feature %s: %w", f.FeatureID, err)
624		}
625		featureRow, err := q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
626			WorkspaceID:   uid,
627			FeatureName:   f.FeatureID,
628			Title:         f.Title,
629			FeatureStatus: ptrStr(f.Status),
630			CurrentStage:  ptrStr(f.CurrentStage),
631			NextAction:    ptrStr(f.NextAction),
632			Stages:        stages,
633			SourcePath:    f.SourcePath,
634			SourceHash:    ptrStr(f.SourceHash),
635		})
636		if err != nil {
637			return fmt.Errorf("upsert feature %s: %w", f.FeatureID, err)
638		}
639	
640		// Upsert documents.
641		docTypes := make([]string, 0, len(f.Documents))
642		for _, d := range f.Documents {
643			_, err := q.UpsertFeatureDocument(ctx, database.UpsertFeatureDocumentParams{
644				WorkspaceID:  uid,
645				FeatureID:    featureRow.ID,
646				FeatureName:  f.FeatureID,
647				DocumentType: d.DocumentType,
648				SourcePath:   d.SourcePath,
649				URL:          ptrStr(d.URL),
650			})
651			if err != nil {
652				return fmt.Errorf("upsert document %s/%s: %w", f.FeatureID, d.DocumentType, err)
653			}
654			docTypes = append(docTypes, d.DocumentType)
655		}
656		if err := q.DeleteFeatureDocumentsNotIn(ctx, database.DeleteFeatureDocumentsNotInParams{
657			WorkspaceID:   uid,
658			FeatureID:     featureRow.ID,
659			DocumentTypes: docTypes,
660		}); err != nil {
661			return fmt.Errorf("delete stale documents for %s: %w", f.FeatureID, err)
662		}
663	
664		// Upsert tasks.
665		taskIDs := make([]string, 0, len(f.Tasks))
666		for _, t := range f.Tasks {
667			if err := upsertTaskSnapshot(ctx, q, uid, featureRow.ID, f.FeatureID, t); err != nil {
668				return err
669			}
670			taskIDs = append(taskIDs, t.TaskID)
671		}
672		if err := q.DeleteFeatureTasksNotIn(ctx, database.DeleteFeatureTasksNotInParams{
673			WorkspaceID: uid,
674			FeatureID:   featureRow.ID,
675			TaskNames:   taskIDs,
676		}); err != nil {
677			return fmt.Errorf("delete stale tasks for %s: %w", f.FeatureID, err)
678		}
679	
680		// Upsert feature-level activity (task_id = nil).
681		if err := upsertFeatureActivity(ctx, q, uid, featureRow.ID, f); err != nil {
682			return err
683		}
684	
685		return nil
686	}
