688	func upsertTaskSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureUUID pgtype.UUID, featureName string, t domain.TaskSnapshot) error {
689		dependsOn, _ := json.Marshal(t.DependsOn) //nolint:errcheck
690		execution, _ := json.Marshal(t.Execution) //nolint:errcheck
691		pr, _ := json.Marshal(t.PR)               //nolint:errcheck
692		wsPr, _ := json.Marshal(t.WorkspacePR)    //nolint:errcheck
693	
694		taskRow, err := q.UpsertWorkspaceTask(ctx, database.UpsertWorkspaceTaskParams{
695			WorkspaceID:   uid,
696			FeatureID:     featureUUID,
697			FeatureName:   featureName,
698			TaskName:      t.TaskID,
699			Title:         t.Title,
700			Repo:          ptrStr(t.Repo),
701			Status:        ptrStr(t.Status),
702			DependsOn:     dependsOn,
703			BlockedReason: ptrStr(t.BlockedReason),
704			Branch:        ptrStr(t.Branch),
705			Execution:     execution,
706			Pr:            pr,
707			WorkspacePr:   wsPr,
708			SourcePath:    t.SourcePath,
709			SourceHash:    ptrStr(t.SourceHash),
710		})
711		if err != nil {
712			return fmt.Errorf("upsert task %s/%s: %w", featureName, t.TaskID, err)
713		}
714	
715		// Upsert task-level activity from the task log.
716		if err := upsertTaskActivity(ctx, q, uid, featureUUID, featureName, taskRow.ID, t); err != nil {
717			return err
718		}
719	
720		return nil
721	}
