723	// upsertFeatureActivity normalizes feature-level activity events (scope_type=feature, task_id=NULL).
724	// Uses the partial unique index on (workspace_id, feature_id, sequence) WHERE task_id IS NULL.
725	func upsertFeatureActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureUUID pgtype.UUID, f domain.FeatureSnapshot) error {
726		for i, evt := range f.Activity {
727			raw, _ := json.Marshal(evt) //nolint:errcheck
728			_, err := q.UpsertFeatureActivityEvent(ctx, database.UpsertFeatureActivityEventParams{
729				WorkspaceID: uid,
730				ScopeType:   "feature",
731				FeatureID:   featureUUID,
732				FeatureName: f.FeatureID,
733				Action:      ptrStr(evt.Action),
734				Actor:       ptrStr(evt.Actor),
735				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
736				Note:        ptrStr(evt.Note),
737				Sequence:    int32(i),
738				RawEvent:    raw,
739			})
740			if err != nil {
741				return fmt.Errorf("upsert feature activity %s[%d]: %w", f.FeatureID, i, err)
742			}
743		}
744		return nil
745	}
746	
747	// upsertTaskActivity normalizes task log entries (scope_type=task).
748	// Uses the partial unique index on (workspace_id, feature_id, task_id, sequence) WHERE task_id IS NOT NULL.
749	func upsertTaskActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureUUID pgtype.UUID, featureName string, taskUUID pgtype.UUID, t domain.TaskSnapshot) error {
750		for i, evt := range t.Activity {
751			raw, _ := json.Marshal(evt) //nolint:errcheck
752			_, err := q.UpsertTaskActivityEvent(ctx, database.UpsertTaskActivityEventParams{
753				WorkspaceID: uid,
754				ScopeType:   "task",
755				FeatureID:   featureUUID,
756				FeatureName: featureName,
757				TaskID:      taskUUID,
758				TaskName:    t.TaskID,
759				Action:      ptrStr(evt.Action),
760				Actor:       ptrStr(evt.Actor),
761				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
762				Note:        ptrStr(evt.Note),
763				Sequence:    int32(i),
764				RawEvent:    raw,
765			})
766			if err != nil {
767				return fmt.Errorf("upsert task activity %s/%s[%d]: %w", featureName, t.TaskID, i, err)
768			}
769		}
770		return nil
771	}
772	
773	// buildFeatureSnapshotFromBatch reconstructs a FeatureSnapshot from pre-fetched rows,
774	// avoiding per-feature database queries.
775	func buildFeatureSnapshotFromBatch(f database.WorkspaceFeature, docs []database.WorkspaceFeatureDocument, tasks []database.WorkspaceTask) domain.FeatureSnapshot {
776		docSnaps := make([]domain.DocumentSnapshot, 0, len(docs))
777		for _, d := range docs {
778			ds := domain.DocumentSnapshot{
779				DocumentType: d.DocumentType,
780				SourcePath:   d.SourcePath,
781			}
782			if d.URL != nil {
783				ds.URL = *d.URL
784			}
785			docSnaps = append(docSnaps, ds)
786		}
787	
788		taskSnaps := make([]domain.TaskSnapshot, 0, len(tasks))
789		for _, t := range tasks {
790			taskSnaps = append(taskSnaps, rowToTaskSnapshot(t))
791		}
792	
793		fs := domain.FeatureSnapshot{
794			FeatureID:  f.FeatureName,
795			Title:      f.Title,
796			SourcePath: f.SourcePath,
797			Documents:  docSnaps,
798			Tasks:      taskSnaps,
799		}
800		if f.FeatureStatus != nil {
801			fs.Status = *f.FeatureStatus
802		}
803		if f.CurrentStage != nil {
804			fs.CurrentStage = *f.CurrentStage
805		}
806		if f.NextAction != nil {
807			fs.NextAction = *f.NextAction
808		}
809		if len(f.Stages) > 0 {
810			var stages map[string]interface{}
811			if err := json.Unmarshal(f.Stages, &stages); err == nil {
812				fs.Stages = stages
813			}
814		}
815		if f.SourceHash != nil {
816			fs.SourceHash = *f.SourceHash
817		}
818		return fs
819	}
820	
821	// rowToTaskSnapshot converts a database row to a domain.TaskSnapshot.
822	func rowToTaskSnapshot(t database.WorkspaceTask) domain.TaskSnapshot {
823		ts := domain.TaskSnapshot{
824			TaskID:     t.TaskName,
825			FeatureID:  t.FeatureName,
826			Title:      t.Title,
827			SourcePath: t.SourcePath,
828		}
829		if t.Repo != nil {
830			ts.Repo = *t.Repo
831		}
832		if t.Status != nil {
833			ts.Status = *t.Status
834		}
835		if t.BlockedReason != nil {
836			ts.BlockedReason = *t.BlockedReason
837		}
838		if t.Branch != nil {
839			ts.Branch = *t.Branch
840		}
841		if t.SourceHash != nil {
842			ts.SourceHash = *t.SourceHash
843		}
844		ts.DependsOn = unmarshalStringSlice(t.DependsOn)
845		if len(t.Execution) > 0 {
846			var m map[string]interface{}
847			_ = json.Unmarshal(t.Execution, &m)
848			ts.Execution = m
849		}
850		if len(t.Pr) > 0 {
851			var m map[string]interface{}
852			_ = json.Unmarshal(t.Pr, &m)
853			ts.PR = m
854		}
855		if len(t.WorkspacePr) > 0 {
856			var m map[string]interface{}
857			_ = json.Unmarshal(t.WorkspacePr, &m)
858			ts.WorkspacePR = m
859		}
860		return ts
861	}
862	
863	// rowToFeatureSummary converts feature row + task list to a domain.FeatureSummary.
864	func rowToFeatureSummary(f database.WorkspaceFeature, tasks []database.WorkspaceTask) domain.FeatureSummary {
865		counts := domain.TaskCounts{}
866		for _, t := range tasks {
867			if t.FeatureName != f.FeatureName {
868				continue
869			}
870			counts.Total++
871			if t.Status == nil {
872				continue
873			}
874			switch *t.Status {
875			case "done":
876				counts.Done++
877			case "in_progress":
878				counts.InProgress++
879			case "blocked":
880				counts.Blocked++
881			case "ready":
882				counts.Ready++
883			case "todo":
884				counts.Todo++
885			}
886		}
887	
888		fs := domain.FeatureSummary{
889			ID:          uuidStr(f.ID),
890			FeatureID:   uuidStr(f.FeatureID),
891			FeatureName: f.FeatureName,
892			Title:       f.Title,
893			UpdatedAt:   f.UpdatedAt.Time,
894			TaskCounts:  counts,
895		}
896		if f.FeatureStatus != nil {
897			fs.Status = *f.FeatureStatus
898		}
899		if f.CurrentStage != nil {
900			fs.CurrentStage = *f.CurrentStage
901		}
902		return fs
903	}
904	
905	// rowToTaskSummary converts a workspace_tasks row to domain.TaskSummary.
906	func rowToTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
907		ts := domain.TaskSummary{
908			ID:          uuidStr(t.ID),
909			TaskID:      uuidStr(t.TaskID),
910			TaskName:    t.TaskName,
911			FeatureID:   uuidStr(t.FeatureID),
912			FeatureName: t.FeatureName,
913			Title:       t.Title,
914		}
915		if t.Status != nil {
916			ts.Status = *t.Status
917		}
918		if t.Repo != nil {
919			ts.Repo = *t.Repo
920		}
921		if t.Branch != nil {
922			ts.Branch = *t.Branch
923		}
924		if t.BlockedReason != nil {
925			ts.BlockedReason = *t.BlockedReason
926			ts.IsBlocked = true
927		}
928		return ts
929	}
930	
931	// rowToActivityEvent converts a database row to domain.ActivityEvent.
932	func rowToActivityEvent(r database.WorkspaceActivityEvent) domain.ActivityEvent {
933		evt := domain.ActivityEvent{
934			Scope: r.ScopeType,
935		}
936		if r.Action != nil {
937			evt.Action = *r.Action
938		}
939		if r.Actor != nil {
940			evt.Actor = *r.Actor
941		}
942		if r.Note != nil {
943			evt.Note = *r.Note
944		}
945		if r.FeatureID.Valid {
946			evt.FeatureID = uuidStr(r.FeatureID)
947		}
948		if r.TaskID.Valid {
949			evt.TaskID = uuidStr(r.TaskID)
950		}
951		if r.OccurredAt != nil {
952			if t, err := time.Parse(time.RFC3339, *r.OccurredAt); err == nil {
953				evt.OccurredAt = t
954			}
955		}
956		return evt
957	}
958	
959	// syncRunRowToDomain converts a database sync run row to domain.SyncRun.
960	func syncRunRowToDomain(r database.WorkspaceSyncRun) *domain.SyncRun {
961		sr := &domain.SyncRun{
962			ID:          uuidStr(r.ID),
963			WorkspaceID: uuidStr(r.WorkspaceID),
964			Trigger:     r.Trigger,
965			Mode:        r.Mode,
966			Status:      domain.SyncStatus(r.Status),
967			StartedAt:   r.StartedAt.Time,
968		}
969		if r.CommitSha != nil {
970			sr.CommitSHA = *r.CommitSha
971		}
972		if r.ErrorCode != nil {
973			sr.ErrorCode = *r.ErrorCode
974		}
975		if r.ErrorMessage != nil {
976			sr.ErrorMsg = *r.ErrorMessage
977		}
978		if r.FinishedAt.Valid {
979			t := r.FinishedAt.Time
980			sr.FinishedAt = &t
981		}
982		return sr
983	}
984	
985	// syncRunToSourceState derives a SourceState from the latest sync run.
986	func syncRunToSourceState(r *database.WorkspaceSyncRun, threshold *time.Duration) domain.SourceState {
987		if r == nil || r.ID == (pgtype.UUID{}) {
988			return domain.StaleState(nil)
989		}
990		thr := domain.DefaultStaleThreshold
991		if threshold != nil {
992			thr = *threshold
993		}
994		return domain.DeriveSourceState(syncRunRowToDomain(*r), thr)
995	}
996	
997	// githubRepoURL fetches the repo URL from workspace_github_sources (best-effort).
998	func githubRepoURL(ctx context.Context, q *database.Queries, uid pgtype.UUID) string {
999		src, err := q.GetGitHubSource(ctx, uid)
1000		if err != nil {
1001			return ""
1002		}
1003		return src.RepoURL
1004	}
