1006	// parseUUID parses a workspace UUID string into pgtype.UUID.
1007	func parseUUID(s string) (pgtype.UUID, error) {
1008		return parseUUIDField(s, "workspace_id")
1009	}
1010	
1011	func (a *Adapter) resolveFeature(ctx context.Context, workspaceID pgtype.UUID, featureIdentifier string) (database.WorkspaceFeature, pgtype.UUID, error) {
1012		if featureUUID, err := parseUUIDField(featureIdentifier, "feature_id"); err == nil {
1013			feature, err := a.q.GetWorkspaceFeature(ctx, database.GetWorkspaceFeatureParams{
1014				WorkspaceID: workspaceID,
1015				FeatureID:   featureUUID,
1016			})
1017			if err == nil {
1018				return feature, feature.ID, nil
1019			}
1020			if !errors.Is(err, pgx.ErrNoRows) {
1021				return database.WorkspaceFeature{}, pgtype.UUID{}, dbErr("get feature", err)
1022			}
1023		}
1024	
1025		feature, err := a.q.GetWorkspaceFeatureByName(ctx, database.GetWorkspaceFeatureByNameParams{
1026			WorkspaceID: workspaceID,
1027			FeatureName: strings.TrimSpace(featureIdentifier),
1028		})
1029		if err != nil {
1030			return database.WorkspaceFeature{}, pgtype.UUID{}, err
1031		}
1032		return feature, feature.ID, nil
1033	}
1034	
1035	func (a *Adapter) resolveTask(ctx context.Context, workspaceID, featureID pgtype.UUID, taskIdentifier string) (database.WorkspaceTask, pgtype.UUID, error) {
1036		if taskUUID, err := parseUUIDField(taskIdentifier, "task_id"); err == nil {
1037			task, err := a.q.GetWorkspaceTask(ctx, database.GetWorkspaceTaskParams{
1038				WorkspaceID: workspaceID,
1039				FeatureID:   featureID,
1040				TaskID:      taskUUID,
1041			})
1042			if err == nil {
1043				return task, task.ID, nil
1044			}
1045			if !errors.Is(err, pgx.ErrNoRows) {
1046				return database.WorkspaceTask{}, pgtype.UUID{}, dbErr("get task", err)
1047			}
1048		}
1049	
1050		task, err := a.q.GetWorkspaceTaskByName(ctx, database.GetWorkspaceTaskByNameParams{
1051			WorkspaceID: workspaceID,
1052			FeatureID:   featureID,
1053			TaskName:    strings.TrimSpace(taskIdentifier),
1054		})
1055		if err != nil {
1056			return database.WorkspaceTask{}, pgtype.UUID{}, err
1057		}
1058		return task, task.ID, nil
1059	}
1060	
1061	// parseUUIDField parses a UUID string into pgtype.UUID with a field-specific validation error.
1062	func parseUUIDField(s, field string) (pgtype.UUID, error) {
1063		var uid pgtype.UUID
1064		if err := uid.Scan(s); err != nil {
1065			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid "+field+": "+s)
1066		}
1067		return uid, nil
1068	}
1069	
1070	// uuidStr renders a pgtype.UUID as a lowercase hyphenated string.
1071	func uuidStr(u pgtype.UUID) string {
1072		if !u.Valid {
1073			return ""
1074		}
1075		b := u.Bytes
1076		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
1077			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
1078	}
1079	
1080	// ptrStr returns nil if s is empty, otherwise returns &s.
1081	func ptrStr(s string) *string {
1082		if s == "" {
1083			return nil
1084		}
1085		return &s
1086	}
1087	
1088	func derefStr(s *string) string {
1089		if s == nil {
1090			return ""
1091		}
1092		return *s
1093	}
1094	
1095	// unmarshalStringSlice decodes a JSON array of strings.
1096	func unmarshalStringSlice(raw json.RawMessage) []string {
1097		if len(raw) == 0 {
1098			return nil
1099		}
1100		var out []string
1101		_ = json.Unmarshal(raw, &out)
1102		return out
1103	}
1104	
1105	// unmarshalExecution decodes execution JSON into domain.ExecutionContext.
1106	func unmarshalExecution(raw json.RawMessage) domain.ExecutionContext {
1107		if len(raw) == 0 {
1108			return domain.ExecutionContext{}
1109		}
1110		var ec domain.ExecutionContext
1111		_ = json.Unmarshal(raw, &ec)
1112		return ec
1113	}
1114	
1115	// dbErr wraps a database error in a domain SourceError.
1116	func dbErr(op string, err error) error {
1117		if strings.Contains(err.Error(), "no rows") {
1118			return domain.NewDatabaseError(domain.ErrDatabaseNotFound, op+": not found")
1119		}
1120		return domain.NewDatabaseError(domain.ErrDatabaseQuery, op+": "+err.Error())
1121	}
